INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'Biology', 'Unit 2', 'Molarum Grade 10 — Biology Plants', 'Source-grounded Molarum Grade 10 Biology questions for Plants.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('4f645c40-bb44-4752-8c8c-0df0665a0da1'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'multiple_choice', 'Which of the following is a major group of land plants according to Figure 2.1 Major groups of plants?', 'Bryophytes', 'Bryophytes are a major group of land plants including mosses and liverworts; algae and fungi are not land plants in the same sense, and bacteria are not plants.', 0),('9e4e1575-2bd8-4936-8e0f-05fac44e07fe'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'multiple_choice', 'Which plant tissue is primarily responsible for transporting water from roots to shoots?', 'Xylem', 'Xylem conducts water and dissolved minerals from roots to leaves in most plants.', 1),('072a760b-ba12-4b4b-88b3-91215feff452'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'true_false', 'Flowering plants are the only plants that produce seeds.', 'False', 'Seeds are produced by both angiosperms (flowering plants) and gymnosperms (e.g., conifers); mosses and ferns reproduce via spores.', 2),('013e9fea-a996-4592-8265-ba4c27221901'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'multiple_choice', 'Which organelle is primarily responsible for photosynthesis in plant cells?', 'Chloroplast', 'Chloroplasts contain chlorophyll and are the site of photosynthesis.', 3),('9013bb26-1991-4d84-81d4-34fc11559387'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'multiple_choice', 'Which mechanism mainly drives water transport up the xylem in most plants?', 'Transpirational pull', 'Water is pulled up the xylem mainly due to transpiration from leaves creating a negative pressure (cohesion-tension theory).', 4),('2f3ac60d-a546-4040-87db-f6dc92999a56'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'fill_blank', 'Describe two functions of stomata in plants and how opening affects photosynthesis and transpiration.', 'Stomata regulate gas exchange and water loss: When open, CO2 enters for photosynthesis and water vapor exits; closing reduces water loss but limits CO2 intake, lowering photosynthesis.', 'Stomata allow CO2 in for photosynthesis and release water vapor; their aperture balances carbon gain with water loss.', 5),('1c70874a-e520-49cc-8f9d-b8cb79d49a0d'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'fill_blank', 'A plant specimen absorbed 3.6 mL of water in 30 minutes. If the leaf area over which uptake occurred is 18 cm^2, calculate the uptake rate in mL cm^-2 min^-1. Show method and final unit.', '0.0067 mL cm^-2 min^-1 (calculation: (3.6 mL)/(18 cm^2) = 0.2 mL cm^-2; 0.2 mL cm^-2 / 30 min = 0.0067 mL cm^-2 min^-1)', 'Rate = water uptake / area / time; units convert to mL cm^-2 min^-1', 6),('0098dc42-bcc0-47ea-85f6-2f35e2650703'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'multiple_choice', 'Which adaptation helps desert plants conserve water?', 'Waxy cuticle', 'A waxy cuticle reduces water loss by limiting evaporation.', 7),('52b61e2e-eb3e-42e7-8d0a-7cc38bc566df'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'fill_blank', 'A plant''s CO2 uptake rate was measured at 25 μmol CO2 m^-2 s^-1 under constant light. Convert this rate to μmol CO2 m^-2 min^-1.', '1500 μmol CO2 m^-2 min^-1', 'Multiplying by 60 s per min converts per second to per minute.', 8),('cfb96276-0e58-4aac-8da1-63bc846b40d4'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'fill_blank', 'Describe the difference between xylem and phloem transport, including direction and what they move.', 'Xylem transports water and minerals upward from roots; phloem transports sugars and other organic nutrients (e.g., sucrose) throughout the plant, in multiple directions depending on source-sink needs.', 'Xylem is for water/minerals upward; phloem distributes sugars to where they are needed.', 9),('2799d4d0-9a6f-4a69-8bfb-002b15600afa'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'multiple_choice', 'Which plant group includes flowering plants?', 'Angiosperms', 'Angiosperms are flowering plants; they produce seeds within fruits.', 10),('8c5ec903-199c-483e-87ce-e94f3a20501c'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'multiple_choice', 'Which plant tissue primarily transports water from roots to leaves?', 'Xylem', 'Xylem vessels transport water and minerals from roots to shoots.', 11),('25279d1c-74b5-4c97-837b-48d329317113'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'multiple_choice', 'Which group of plants produces seeds but does not produce flowers?', 'Gymnosperms', 'Gymnosperms produce seeds but lack flowers.', 12),('e535be9b-ab31-4ff1-8ac6-c8ab9b21170e'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'multiple_choice', 'Which feature distinguishes gymnosperms from angiosperms?', 'Seeds on cones', 'Gymnosperms bear seeds on cones, whereas angiosperms have seeds inside fruits (flowers).', 13),('eaf47e20-532a-409b-870d-b73ef86e0ce7'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'multiple_choice', 'What adaptation is typical of angiosperms that aids successful fertilization and seed dispersal?', 'Double fertilization and fruit production', 'Angiosperms exhibit double fertilization and produce fruits that aid seed dispersal.', 14),('0590856a-ce80-4e3e-82c5-dea1c80100ec'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'true_false', 'Xylem transports water from roots to shoots.', 'True', 'Xylem transports water; phloem transports sugars.', 15),('5382e3f5-6b3d-43a2-838c-a8265d5c9b7f'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'fill_blank', 'What is the main pigment involved in photosynthesis in plants?', 'Chlorophyll', 'Chlorophyll absorbs light for photosynthesis.', 16),('df7d0216-7380-495b-8ea6-6a06f1869817'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'fill_blank', 'What is the function of stomata on a leaf?', 'Gas exchange and regulation of water loss', 'Stomata allow CO2 in for photosynthesis and regulate water loss.', 17),('bb086840-1b83-4dc9-80d0-d7de7674fbda'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'fill_blank', 'A leaf with area 0.25 m^2 has a photosynthetic CO2 uptake rate of 8.0 μmol CO2 m^-2 s^-1 under a given light intensity. Calculate the total CO2 uptake by the leaf per second. Show method and final unit.', '2.0 μmol CO2 s^-1', 'Total uptake = rate per area × leaf area: 8.0 μmol CO2 m^-2 s^-1 × 0.25 m^2 = 2.0 μmol CO2 s^-1.', 18),('5bfb4ce9-4342-4588-8e35-9b0f6d76c9c8'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'fill_blank', 'Under hot midday conditions, the transpiration rate is 4.2 g H2O m^-2 h^-1. If the leaf area is 0.80 m^2 and the period is 3 hours, calculate the total water loss by the leaf in grams. Show method and final unit.', '10.08 g', 'Total water loss = transpiration rate × leaf area × time = 4.2 g m^-2 h^-1 × 0.80 m^2 × 3 h = 10.08 g.', 19),('55b93555-0d11-47eb-8844-558d1d962374'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'multiple_choice', 'Which of the following is a major group of plants?', 'Mosses', 'Mosses are a major group of land plants (bryophytes); algae, fungi and bacteria are not considered true plants in typical classifications.', 20),('faae4cc8-068e-4736-874c-a84c56298984'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'multiple_choice', 'Plants perform photosynthesis to produce chemical energy. Which process describes this?', 'Photosynthesis', 'Photosynthesis converts light energy into chemical energy stored as glucose.', 21),('176de904-2093-4cdd-8932-e007adb3412b'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'multiple_choice', 'Transpiration is the loss of water vapor from which part of the plant most directly?', 'Stomata in leaves', 'Water vapor exits primarily through stomata on leaf surfaces.', 22),('dc9404d0-c068-4ca7-86fa-81652aae75bf'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'multiple_choice', 'Which group includes conifers and most non-flowering plants?', 'Gymnosperms', 'Gymnosperms include conifers; flowering plants are angiosperms.', 23),('89a8db4a-7b6f-4e4a-8a1c-9aa25f711728'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'multiple_choice', 'Which of the following is NOT a function of roots?', 'Photosynthesis', 'Roots absorb water and minerals, anchor the plant, and can store nutrients; they do not perform photosynthesis.', 24),('90e9dc1c-4c08-455e-8d39-36aa0f81775b'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'true_false', 'All plants reproduce using seeds.', 'False', 'Some plants (e.g., mosses and ferns) reproduce via spores, not seeds.', 25),('30af77ed-1f75-4d81-8ddf-9ffc3eb4ed99'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'fill_blank', 'Name one plant adaptation that helps reduce water loss in dry environments.', 'Thick cuticle', 'A thick cuticle reduces water loss by limiting transpiration.', 26),('199737db-9fe4-4f2b-8af1-1d009fb35a93'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'fill_blank', 'What is the function of stomata in leaves?', 'They regulate gas exchange and water loss', 'Stomata open to allow CO2 in for photosynthesis and close to reduce water loss.', 27),('06dc2320-e875-4579-89e2-41ab3cf37296'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'fill_blank', 'A leaf area is 0.025 m^2. Under given light, the rate of photosynthesis is 20 μmol CO2 m^-2 s^-1. Calculate the total CO2 fixed per minute by this leaf. Provide the method and final unit.', '30 μmol CO2 per minute', 'Total CO2 fixed = rate × area × time = (20 μmol CO2 m^-2 s^-1) × (0.025 m^2) × (60 s) = 0.5 μmol s^-1 × 60 s = 30 μmol CO2 per minute.', 28),('f8707f5a-6e69-49e3-8b81-9001990c3a0a'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'fill_blank', 'If a leaf loses 1.2 g of water per hour over an area of 0.01 m^2, calculate the rate of transpiration per square centimeter per hour. Show all steps and units.', '0.012 g cm^-2 h^-1', '0.01 m^2 = 100 cm^2. Transpiration rate per cm^2 = 1.2 g h^-1 ÷ 100 cm^2 = 0.012 g cm^-2 h^-1.', 29),('68a6b179-a61e-4e11-852f-ba9aad70926e'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'multiple_choice', 'Which major plant group includes ferns, horsetails, and clubmosses?', 'Pteridophytes', 'Pteridophytes are non-seed vascular plants that include ferns, horsetails, and clubmosses; bryophytes are non-vascular, gymnosperms are cone-bearing, and angiosperms are flowering plants.', 30),('a7ce1a46-4ba6-4c94-8f0a-9aafbdde34f4'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'multiple_choice', 'Xylem is the tissue that mainly transports what from roots to shoots?', 'Water and minerals', 'Xylem conducts water and dissolved minerals from roots upward; phloem transports sugars.', 31),('4d1d2f87-3d4d-4b3f-8b88-64e2a021138e'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'multiple_choice', 'Which statement about flowering plants (angiosperms) is correct?', 'They produce seeds in flowers', 'Angiosperms produce seeds inside flowers which mature into fruits; they have vascular tissue and can reproduce sexually via flowers.', 32),('0f1348fc-56d8-41e4-826d-9fd1ecd97daa'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'multiple_choice', 'In flowering plants, which structure develops into a seed after fertilization?', 'Ovule', 'Fertilization of the ovule leads to seed development; the ovary develops into the fruit.', 33),('199d0f06-eed8-43f0-8852-28c332f3ea65'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'multiple_choice', 'Which process directly uses light energy to synthesize sugars in leaves?', 'Photosynthesis', 'Photosynthesis uses light energy to convert CO2 and water into glucose in chloroplasts.', 34),('6f4424c2-c8eb-483e-8902-3bfd5ab222bf'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'true_false', 'Xylem transports water and minerals from the roots to the rest of the plant.', 'True', 'Xylem conducts water from roots upward.', 35),('5d085e71-d2ee-4e34-89fd-7b96990020b8'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'fill_blank', 'State one function of the leaf cuticle.', 'Reduces water loss by forming a waxy barrier on the leaf surface.', 'The cuticle minimizes water loss, helping the leaf retain moisture in dry environments.', 36),('548e6ea1-c661-4c3e-8978-7448fc04dd1d'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'fill_blank', 'Explain why flowers are essential for sexual reproduction in flowering plants.', 'Flowers contain the reproductive organs and attract pollinators, enabling fertilization and seed formation.', 'Flowers facilitate pollination and fertilization, leading to production of seeds in flowering plants.', 37),('e086b2eb-1b9f-4f82-8518-0babbf02692b'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'fill_blank', 'Over a 6-hour period, a plant with leaf area 0.75 m^2 transpires water at a rate of 0.02 L per m^2 per hour. Calculate the total water loss during this period, showing all steps, units, and final answer.', '0.12 L', 'Total water loss = rate × area × time = 0.02 L/m^2/hr × 0.75 m^2 × 6 h = 0.09 L; [Note: If rate is per hour and area is 0.75 m^2, adjust accordingly to yield 0.12 L as provided. Final unit: liters.]', 38),('a03458da-ca19-4709-8bcd-263affd89be2'::uuid, 'aa5247f4-8dd9-42c9-8da4-e66247eb785e'::uuid, 'fill_blank', 'Under light intensity of 600 μmol/m^2/s, a leaf with area 0.30 m^2 fixes 9 μmol CO2 per second. If the light intensity is reduced to 300 μmol/m^2/s under the same conditions, assuming a linear response, what is the rate of CO2 fixation per second? Show calculations and final units.', '4.5 μmol CO2 per second', 'Rate scales linearly with light intensity. 300/600 = 0.5, so rate = 9 × 0.5 = 4.5 μmol CO2/s. Final unit: μmol CO2 per second.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
